def advisor(scope, time, cost, flex):
    # exactly two corners are fixed; the named one must move
    if flex == 'scope':
        return 'max scope: %d' % (time * cost)
    if flex == 'time':
        return 'min time: %.1f months' % (scope / cost)
    return 'min cost: %.1f devs' % (scope / time)

